package uy.negocio.offline

import android.app.*
import android.os.Bundle
import android.content.Intent
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.Canvas
import android.graphics.Paint
import android.content.ActivityNotFoundException
import android.net.Uri
import android.view.View
import android.widget.*
import java.time.LocalDate
import java.time.LocalTime
import java.time.YearMonth
import java.time.format.DateTimeFormatter
import java.text.NumberFormat
import java.util.Locale
import java.math.BigDecimal
import java.math.RoundingMode

class MainActivity:Activity() {
 private lateinit var db:Database
 private lateinit var root:LinearLayout
 private val prefs by lazy { getSharedPreferences("settings",MODE_PRIVATE) }
 private val fmt=DateTimeFormatter.ofPattern("dd/MM/yyyy")
 private val es=Locale("es","UY")
 private var selected=LocalDate.now()
 private var screen="home"
 private var action=""
 private val createCode=101
 private val openCode=102
 private val accent=Color.rgb(117,57,111)
 override fun onCreate(savedInstanceState:Bundle?) { super.onCreate(savedInstanceState);db=Database(this);if(prefs.getString("pin","")!!.isNotEmpty()) lock() else home() }
 private fun text(s:String,size:Float=17f,bold:Boolean=false)=TextView(this).apply { text=s;textSize=size;setTextColor(Color.rgb(43,36,44));setPadding(9,12,9,12);if(bold)setTypeface(null,Typeface.BOLD) }
 private fun button(s:String,fn:()->Unit)=Button(this).apply { text=s;setTextColor(Color.WHITE);backgroundTintList=android.content.res.ColorStateList.valueOf(accent);setOnClickListener { try { fn() } catch(e:Exception) { toast("Error: ${e.message}") } } }
 private fun field(h:String,value:String="",numeric:Boolean=false)=EditText(this).apply { hint=h;setText(value);setSingleLine(true);if(numeric) inputType=android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL }
 private fun setup(title:String,kind:String) { screen=kind;root=LinearLayout(this).apply { orientation=LinearLayout.VERTICAL;setPadding(20,if(kind=="home") 15 else (resources.displayMetrics.ydpi * 1.5f / 2.54f).toInt(),20,24);setBackgroundColor(Color.rgb(250,247,250)) };setContentView(ScrollView(this).apply { isFillViewport=true;addView(root) });if(kind!="home")root.addView(button("‹ Menú principal") { home() });root.addView(text(title,25f,true)) }
 private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_LONG).show()
 private fun money(c:Long)=NumberFormat.getCurrencyInstance(es).format(BigDecimal.valueOf(c,2))
 private fun profit(c:Long)=BigDecimal.valueOf(c).multiply(BigDecimal.valueOf(prefs.getInt("percentage",40).toLong())).divide(BigDecimal(100),0,RoundingMode.HALF_UP).longValueExact()
 private fun amount(s:String):Long?=runCatching { val n=BigDecimal(s.trim().replace(",",".")).setScale(2,RoundingMode.HALF_UP);if(n<=BigDecimal.ZERO)null else n.movePointRight(2).longValueExact() }.getOrNull()
 private fun dateButton(date:LocalDate,fn:(LocalDate)->Unit) { root.addView(button("Fecha: ${date.format(fmt)}") { DatePickerDialog(this,{_,y,m,d->fn(LocalDate.of(y,m+1,d))},date.year,date.monthValue-1,date.dayOfMonth).show() }) }
 private fun timeButton(t:String,fn:(String)->Unit) { root.addView(button("Hora: $t") { val p=t.split(":");TimePickerDialog(this,{_,h,m->fn("%02d:%02d".format(h,m))},p[0].toInt(),p[1].toInt(),true).show() }) }
 private fun confirm(message:String,fn:()->Unit) { AlertDialog.Builder(this).setTitle("Confirmar").setMessage(message).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar") { _,_->fn() }.show() }
 private fun <T> chooser(title:String,items:List<T>,label:(T)->String,chosen:(T)->Unit) { if(items.isEmpty()) { toast("No hay opciones registradas");return };AlertDialog.Builder(this).setTitle(title).setItems(items.map(label).toTypedArray()) { _,which->chosen(items[which]) }.show() }
 private fun home() { setup(prefs.getString("business_name","Salón Boutique")?:"Salón Boutique","home");
 val titleRow=LinearLayout(this).apply { orientation=LinearLayout.HORIZONTAL;gravity=android.view.Gravity.CENTER_VERTICAL }
 titleRow.addView(text(prefs.getString("business_name","Salón Boutique")?:"Salón Boutique",22f,true),LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f))
 titleRow.addView(button("✎") { val input=field("Nombre del negocio",prefs.getString("business_name","Salón Boutique")?:"Salón Boutique");AlertDialog.Builder(this).setTitle("Editar nombre del negocio").setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Guardar") { _,_->val n=input.text.toString().trim();if(n.isNotBlank()) { prefs.edit().putString("business_name",n).apply();home() } }.show() })
 root.removeViewAt(root.childCount-1);root.addView(titleRow)
 addHomeCharts();root.addView(text("Agenda y cobros sin internet",15f));root.addView(button("📅 TODOS LOS TURNOS") { agenda() });root.addView(button("💰 INGRESOS") { incomes() });root.addView(button("✂ SERVICIOS Y PRECIOS") { services() });root.addView(button("👤 HISTORIAL DE CLIENTAS") { clients() });root.addView(button("💾 COPIAS DE SEGURIDAD / DRIVE") { backups() });root.addView(button("⚙ AJUSTES Y PIN") { settings() });val today=LocalDate.now().toString();val sum=db.payments().filter { it.date==today }.sumOf { it.amountCents };root.addView(text("Hoy: ${money(sum)} · 40% o porcentaje configurado: ${money(profit(sum))}"));root.addView(text("Turnos de hoy: ${db.appointments().count { it.date==today && it.status!="Cancelado" }}")) }
 private fun agenda() { setup("Todos los turnos","agenda");root.addView(button("+ Añadir turno") { editAppointment() });root.addView(button("Calendario mensual") { calendar() });root.addView(text("Todos los turnos ordenados por fecha y hora",17f,true));val list=db.appointments();if(list.isEmpty())root.addView(text("Todavía no hay turnos."));list.forEach { a->root.addView(text("${a.date} · ${a.time} · ${a.name}\n${a.service} (${a.duration} min) · ${a.status}",17f,true));root.addView(button("Editar · ${a.name}") { editAppointment(a) });root.addView(button("Eliminar") { confirm("¿Eliminar turno de ${a.name}?") { db.delete("appointments",a.id);agenda() } });root.addView(View(this).apply { minimumHeight=12 }) } }
 private fun calendar() { setup("Calendario mensual","calendar");var month=YearMonth.from(selected);fun render() { root.removeViews(2,root.childCount-2);root.addView(button("‹ Mes anterior") { selected=selected.minusMonths(1);calendar() });root.addView(text("${month.month} ${month.year}",21f,true));root.addView(button("Mes siguiente ›") { selected=selected.plusMonths(1);calendar() });val counts=db.appointments().filter { it.date.startsWith(month.toString()) }.groupingBy { it.date }.eachCount();for(day in 1..month.lengthOfMonth()) { val d=month.atDay(day);root.addView(button("${d.format(fmt)} · ${counts[d.toString()]?:0} turnos") { selected=d;val list=db.appointments().filter { it.date==d.toString() };chooser("Turnos ${d.format(fmt)}",list,{"${it.time} ${it.name} · ${it.service}"}) { editAppointment(it) } }) } };render() }
 private fun editAppointment(old:Appointment?=null) { setup(if(old==null)"Nuevo turno" else "Editar turno","edit");var date=old?.date?.let(LocalDate::parse)?:selected;var time=old?.time?:"09:00";val name=field("Nombre",old?.name?:"");val service=field("Servicio",old?.service?:"");val phone=field("Teléfono (opcional)",old?.phone?:"");val minutes=field("Duración en minutos",(old?.duration?:60).toString(),true);var status=old?.status?:"Pendiente";fun draw() { root.removeViews(2,root.childCount-2);dateButton(date) { date=it;draw() };timeButton(time) { time=it;draw() };root.addView(name);root.addView(service);root.addView(phone);root.addView(minutes);root.addView(button("Elegir servicio del catálogo") { chooser("Servicios",db.services(),{ "${it.name} · ${money(it.priceCents)}" }) { service.setText(it.name);minutes.setText(it.minutes.toString()) } });root.addView(button("Estado: $status") { chooser("Estado",listOf("Pendiente","Realizado","Cancelado"),{it}) { status=it;draw() } });root.addView(button("Guardar turno") { val n=name.text.toString().trim();val s=service.text.toString().trim();val m=minutes.text.toString().toIntOrNull();if(n.isEmpty()||s.isEmpty()||m==null||m !in 1..1440) { toast("Completá nombre, servicio y duración válida");return@button };val a=Appointment(old?.id?:0,date.toString(),time,n,s,phone.text.toString().trim(),m,status);if(status!="Cancelado" && db.conflicts(a)) { toast("El horario se superpone con otro turno");return@button };db.saveAppointment(a);selected=date;agenda();toast("Turno guardado") }) };draw() }
 private fun incomes() { setup("Ingresos","incomes");root.addView(button("+ Añadir cobro") { editPayment() });root.addView(button("Exportar cobros CSV") { export("payments") });root.addView(button("Exportar agenda CSV") { export("appointments") });val all=db.payments();val today=LocalDate.now();val sum=all.filter { it.date==today.toString() }.sumOf { it.amountCents };val month=all.filter { it.date.startsWith(today.toString().take(7)) }.sumOf { it.amountCents };val total=all.sumOf { it.amountCents };root.addView(text("Hoy: ${money(sum)} · Ganancia estimada: ${money(profit(sum))}"));root.addView(text("Mes: ${money(month)} · Ganancia estimada: ${money(profit(month))}"));root.addView(text("Histórico: ${money(total)} · Ganancia estimada: ${money(profit(total))}"));var filter="";val query=field("Filtrar por fecha (AAAA-MM) o servicio");root.addView(query);val results=LinearLayout(this).apply { orientation=LinearLayout.VERTICAL };root.addView(results);fun show() { results.removeAllViews();filter=query.text.toString().trim();val list=all.filter { filter.isBlank()||it.date.contains(filter,true)||it.service.contains(filter,true) };results.addView(text("${list.size} cobros",16f,true));list.forEach { p->results.addView(text("${p.date} · ${p.service} · ${money(p.amountCents)}"));results.addView(button("Editar cobro") { editPayment(p) });results.addView(button("Eliminar cobro") { confirm("¿Eliminar ${money(p.amountCents)}?") { db.delete("payments",p.id);incomes() } }) } };query.addTextChangedListener(object:android.text.TextWatcher { override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){show()};override fun afterTextChanged(s:android.text.Editable?){} });show() }
 private fun editPayment(old:Payment?=null) { setup(if(old==null)"Añadir cobro" else "Editar cobro","edit");var date=old?.date?.let(LocalDate::parse)?:LocalDate.now();val value=field("Importe en pesos",old?.let { BigDecimal.valueOf(it.amountCents,2).toPlainString() }?:"",true);val service=field("Servicio o venta",old?.service?:"");fun draw() { root.removeViews(2,root.childCount-2);dateButton(date) { date=it;draw() };root.addView(value);root.addView(service);root.addView(button("Elegir servicio del catálogo") { chooser("Servicios",db.services(),{"${it.name} · ${money(it.priceCents)}"}) { service.setText(it.name);value.setText(BigDecimal.valueOf(it.priceCents,2).toPlainString()) } });root.addView(button("Guardar cobro") { val cents=amount(value.text.toString());val s=service.text.toString().trim();if(cents==null||s.isEmpty()) { toast("Importe positivo y servicio obligatorios");return@button };db.savePayment(Payment(old?.id?:0,date.toString(),cents,s,old?.appointmentId));incomes();toast("Cobro guardado") }) };draw() }
 private fun services() { setup("Servicios y precios","services");root.addView(button("+ Nuevo servicio") { editService() });db.services().forEach { s->root.addView(text("${s.name} · ${money(s.priceCents)} · ${s.minutes} min"));root.addView(button("Editar servicio") { editService(s) });root.addView(button("Eliminar servicio") { confirm("¿Eliminar servicio?") { db.delete("services",s.id);services() } }) } }
 private fun editService(old:Service?=null) { setup("Servicio","edit");val name=field("Nombre",old?.name?:"");val price=field("Precio",old?.let { BigDecimal.valueOf(it.priceCents,2).toPlainString() }?:"",true);val mins=field("Duración en minutos",(old?.minutes?:60).toString(),true);root.addView(name);root.addView(price);root.addView(mins);root.addView(button("Guardar") { val n=name.text.toString().trim();val p=amount(price.text.toString());val m=mins.text.toString().toIntOrNull();if(n.isEmpty()||p==null||m==null||m !in 1..1440) { toast("Datos inválidos");return@button };db.saveService(Service(old?.id?:0,n,p,m));services() }) }
 private fun clients() { setup("Fichas de clientas","clients");root.addView(button("+ Nueva ficha") { val input=field("Nombre de la clienta");AlertDialog.Builder(this).setTitle("Nueva clienta").setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Continuar") { _,_->val n=input.text.toString().trim();if(n.isNotBlank())clientDetail(n) }.show() });val names=(db.appointments().map { it.name }+db.profileNames()).distinct().sorted();if(names.isEmpty())root.addView(text("Todavía no hay clientas registradas."));names.forEach { n->root.addView(button(n) { clientDetail(n) }) } }
 private fun clientDetail(name:String) { setup("Ficha de $name","client");val (savedPhone,savedNotes)=db.profile(name);val phoneFromTurn=db.appointments().firstOrNull { it.name.equals(name,true) && it.phone.isNotBlank() }?.phone?:"";val phone=field("Teléfono",savedPhone.ifBlank { phoneFromTurn });phone.inputType=android.text.InputType.TYPE_CLASS_PHONE;val notes=field("Observaciones",savedNotes);notes.setSingleLine(false);notes.minLines=3;root.addView(phone);root.addView(notes);root.addView(button("Guardar ficha") { db.saveProfile(name,phone.text.toString().trim(),notes.text.toString().trim());toast("Ficha guardada") });root.addView(button("Enviar recordatorio por WhatsApp") { val p=phone.text.toString().filter(Char::isDigit);if(p.isBlank()) { toast("Primero escribí el teléfono de la clienta");return@button };val next=db.appointments().filter { it.name.equals(name,true) && it.status!="Cancelado" && it.date>=LocalDate.now().toString() }.minWithOrNull(compareBy<Appointment> { it.date }.thenBy { it.time });if(next==null) { toast("No hay próximos turnos");return@button };val message="Hola $name, te recordamos tu turno en ${prefs.getString("business_name","Salón Boutique")} para ${next.service} el ${next.date} a las ${next.time}. ¡Te esperamos!";val uri=Uri.parse("https://wa.me/$p?text="+Uri.encode(message));try { startActivity(Intent(Intent.ACTION_VIEW,uri)) } catch(e:ActivityNotFoundException) { toast("No se encontró una aplicación para abrir WhatsApp") } });root.addView(text("Historial de turnos",20f,true));db.appointments().filter { it.name.equals(name,true) }.forEach { a->root.addView(text("${a.date} ${a.time} · ${a.service} · ${a.status}")) } }
 private fun addHomeCharts() { val payments=db.payments();val today=LocalDate.now();val days=(6 downTo 0).map { today.minusDays(it.toLong()) };root.addView(text("Ingresos por día (últimos 7 días)",18f,true));root.addView(BarChart(days.map { it.dayOfMonth.toString() },days.map { day->payments.filter { it.date==day.toString() }.sumOf { it.amountCents } }));val months=(5 downTo 0).map { YearMonth.from(today).minusMonths(it.toLong()) };root.addView(text("Ingresos por mes (últimos 6 meses)",18f,true));root.addView(BarChart(months.map { "%02d/%02d".format(it.monthValue,it.year%100) },months.map { month->payments.filter { it.date.startsWith(month.toString()) }.sumOf { it.amountCents } })) }
 private inner class BarChart(private val labels:List<String>,private val amounts:List<Long>):View(this@MainActivity) { private val paint=Paint(3);override fun onMeasure(w:Int,h:Int) { setMeasuredDimension(View.MeasureSpec.getSize(w), (205*resources.displayMetrics.density).toInt()) };override fun onDraw(canvas:Canvas) { super.onDraw(canvas);val density=resources.displayMetrics.density;val left=18f*density;val top=22f*density;val bottom=height-35f*density;val max=(amounts.maxOrNull()?:0L).coerceAtLeast(1L).toDouble();val space=(width-2*left)/labels.size;paint.color=Color.LTGRAY;paint.strokeWidth=density;canvas.drawLine(left,bottom,width-left,bottom,paint);labels.forEachIndexed { i,label->val x=left+space*(i+0.5f);val barHeight=((bottom-top)*amounts[i]/max).toFloat();paint.color=accent;canvas.drawRoundRect(x-space*0.28f,bottom-barHeight,x+space*0.28f,bottom,5f,5f,paint);paint.color=Color.DKGRAY;paint.textSize=11f*density;paint.textAlign=Paint.Align.CENTER;canvas.drawText(label,x,bottom+16*density,paint);canvas.drawText(money(amounts[i]),x,(bottom-barHeight-5*density).coerceAtLeast(12*density),paint) } } }

 private fun settings() { setup("Ajustes","settings");val percent=field("Porcentaje de ganancia",prefs.getInt("percentage",40).toString(),true);root.addView(percent);root.addView(button("Guardar porcentaje") { val v=percent.text.toString().toIntOrNull();if(v==null||v !in 0..100) { toast("Usá un porcentaje de 0 a 100");return@button };prefs.edit().putInt("percentage",v).apply();toast("Guardado") });val pin=field("Nuevo PIN de 4 a 8 números");pin.inputType=android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD;root.addView(pin);root.addView(button("Activar / cambiar PIN") { val s=pin.text.toString();if(s.length !in 4..8||!s.all(Char::isDigit)) { toast("PIN de 4 a 8 dígitos");return@button };prefs.edit().putString("pin",s).apply();toast("PIN activado") });root.addView(button("Desactivar PIN") { confirm("¿Desactivar el PIN? (Se necesita desbloquear la aplicación para acceder a este menú)") { prefs.edit().remove("pin").apply();toast("PIN desactivado") } }) }
 private fun lock() { val input=field("PIN");input.inputType=android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD;AlertDialog.Builder(this).setTitle("Desbloquear agenda").setView(input).setCancelable(false).setPositiveButton("Entrar") { _,_->if(input.text.toString()==prefs.getString("pin",""))home() else lock() }.show() }
 private fun backups() { setup("Copias de seguridad","backups");root.addView(text("Guardá una copia completa en Drive eligiendo Google Drive en el selector de archivos. No se sube automáticamente y no requiere permiso de internet de esta app."));root.addView(button("Guardar copia en Drive o dispositivo") { saveFile("backup","respaldo-agenda-${LocalDate.now()}.json","application/json") });root.addView(button("Restaurar copia desde Drive o dispositivo") { confirm("Restaurar reemplazará todos los turnos, cobros y servicios actuales. Guardá antes una copia.") { val i=Intent(Intent.ACTION_OPEN_DOCUMENT).apply { addCategory(Intent.CATEGORY_OPENABLE);type="*/*" };startActivityForResult(i,openCode) } });root.addView(text("La copia no incluye el PIN de acceso. La restauración es transaccional: si falla, conserva los registros anteriores.",14f)) }
 private fun saveFile(kind:String,filename:String,mime:String) { action=kind;val i=Intent(Intent.ACTION_CREATE_DOCUMENT).apply { addCategory(Intent.CATEGORY_OPENABLE);type=mime;putExtra(Intent.EXTRA_TITLE,filename) };startActivityForResult(i,createCode) }
 private fun export(kind:String) { saveFile(kind,if(kind=="payments")"ingresos.csv" else "agenda.csv","text/csv") }
 private fun csvCell(s:String)="\""+s.replace("\"","\"\"")+"\""
 private fun csv(kind:String):String { val lines=mutableListOf<String>();if(kind=="payments") { lines.add("Fecha,Servicio,Ingreso_UYU,Ganancia_UYU");db.payments().forEach { p->lines.add(listOf(p.date,p.service,BigDecimal.valueOf(p.amountCents,2).toPlainString(),BigDecimal.valueOf(profit(p.amountCents),2).toPlainString()).joinToString(",",transform=::csvCell)) } } else { lines.add("Fecha,Hora,Clienta,Servicio,Telefono,Duracion,Estado");db.appointments().forEach { a->lines.add(listOf(a.date,a.time,a.name,a.service,a.phone,a.duration.toString(),a.status).joinToString(",",transform=::csvCell)) } };return "\uFEFF"+lines.joinToString("\r\n",postfix="\r\n") }
 override fun onActivityResult(requestCode:Int,resultCode:Int,data:Intent?) { super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK)return;val uri=data?.data?:return;try { if(requestCode==openCode) { val content=contentResolver.openInputStream(uri)?.bufferedReader(Charsets.UTF_8)?.use { it.readText() }?:error("No se pudo leer");db.restore(content);toast("Copia restaurada");home() } else if(requestCode==createCode) { val output=contentResolver.openOutputStream(uri)?:error("No se pudo escribir");output.use { stream->val content=if(action=="backup")db.backup() else csv(action);stream.write(content.toByteArray(Charsets.UTF_8)) };toast("Archivo guardado") } } catch(e:Exception) { toast("Operación fallida: ${e.message}") } }
 override fun onBackPressed() { if(screen=="home")super.onBackPressed() else home() }
}
